function placeAgents(L,z){const plan=[['agent','rogue','firewall','agent'],['rogue','agent','firewall','viking','agent'],['agent','enforcer','firewall','viking','agent','enforcer'],['enforcer','viking','firewall','agent','rogue','enforcer'],['rogue','viking','firewall','enforcer']][z]||[];
 const end=(L.launchX||L.arena.x)-300,start=560;if(end<=start)return;
 const ok=(px,type)=>L.solids.some(s=>s.ground&&s.x<=px-110&&s.x+s.w>=px+110)&&!L.solids.some(s=>s.rack&&Math.abs(s.x+s.w/2-px)<140)&&!L.terminals.some(t=>Math.abs(t.x-px)<150)&&!L.hazards.some(h=>Math.abs(h.x-px)<130)&&!L.enemies.some(e=>['agent','enforcer','crawler','turret','viking','rogue','firewall'].includes(e.type)&&Math.abs(e.x-px)<(type==='firewall'||e.type==='firewall'?220:120))&&!L.fans.some(f=>{const m=type==='firewall'?300:120;return px>f.x-m&&px<f.x+f.w+m})&&(type!=='firewall'||!L.hazards.some(h=>Math.abs(h.x-px)<200));
 plan.forEach((type,i)=>{const target=start+(end-start)*(i+0.5)/plan.length;for(let d=0;d<3200;d+=15){for(const px of [target+d,target-d]){if(px>start&&px<end&&ok(px,type)){L.enemies.push(makeEnemy(type,px,undefined,{atk:null,at:0,cd:90+i*25}));return}}}})}
function makeBoss(z,ax){
 const b={z,active:false,dead:false,t:0,flash:0,encrypted:false,keyDone:false,hidden:false,state:'walk',st:0};
 if(z===0)return Object.assign(b,{name:'ROGUE ORCHESTRATOR',x:ax+600,y:150,w:110,h:110,hp:40,maxHp:40});
 if(z===1)return Object.assign(b,{name:'PROMPT INJECTOR',x:ax+700,y:FLOOR-180,w:190,h:120,hp:46,maxHp:46});
 if(z===2)return Object.assign(b,{name:'THERMAL OVERLORD',x:ax+700,y:FLOOR-170,w:120,h:170,hp:54,maxHp:54});
 if(z===3)return Object.assign(b,{name:'DROP TABLE HYDRA',x:ax+700,y:FLOOR,w:80,h:150,hp:56,maxHp:56,holes:[ax+200,ax+470,ax+740],hole:2,state:'hidden'});
 return Object.assign(b,{name:'NULL.js',x:ax+AW-240,y:180,w:160,h:150,hp:80,maxHp:80});
}

