function binaryRain(alpha){const cw=30,off=-(camera*0.3)%cw;for(let i=-1;i<W/cw+1;i++){const col=i+Math.floor(camera*0.3/cw),sp=1.2+rnd(col)*2.4,y0=((ticks*sp+rnd(col*3)*900)%(H+260))-160;if(rnd(col*7)<0.45)continue;for(let j=0;j<7;j++){const y=y0-j*18;if(y<-20||y>H+20)continue;c.globalAlpha=(1-j/7)*alpha;c.drawImage(glyph(rnd(col*13+j+Math.floor(ticks/7))>0.5?'1':'0',j===0?'#e6fff0':(col%4===0?'#ff4fa8':'#36ff8a')),Math.round(off+i*cw+cw/2-8),Math.round(y-15))}}c.globalAlpha=1}
