function wrap(s,n){const out=[];let line='';for(const wd of s.split(' ')){if((line+' '+wd).trim().length>n){out.push(line.trim());line=wd}else line+=' '+wd}if(line.trim())out.push(line.trim());return out.length?out:['']}
