 const g=$('briefSkills');g.innerHTML='';for(const l of LESSONS.filter(l=>l.zone===zone)){const d=document.createElement('div');const s=document.createElement('strong');s.textContent=l.typed?'TYPE IT':'CHOOSE IT';d.appendChild(s);d.appendChild(document.createTextNode(l.title));g.appendChild(d)}
 const d=document.createElement('div');const s=document.createElement('strong');s.textContent='BOSS';d.appendChild(s);d.appendChild(document.createTextNode(Z.boss));g.appendChild(d);
