let attempts=0;
function openPuzzle(t){if(!t.bossKey&&!cutSeen.has('term'+zone)){playCut('terminal',[0,1,2,3,4,5,6,7],38,()=>openPuzzle0(t),'term'+zone);return}openPuzzle0(t)}
function openPuzzle0(t){activeTerm=t;attempts=0;mode='puzzle';releaseControls();SFX.term();const l=LESSONS[t.lesson],zl=LESSONS.filter(x=>x.zone===l.zone);
 $('codeSector').textContent=t.bossKey?'DECRYPT KEY // NULL.js':`CODE NODE // ${ZONES[zone].name}`;$('codeProgress').textContent=`PATCH ${zl.indexOf(l)+1} OF ${zl.length}`;
 $('codeTitle').textContent=l.title;$('codeQuestion').textContent=l.question;$('codeSnippet').textContent=l.snippet;
 const ch=$('codeChoices');ch.innerHTML='';$('codeContinue').hidden=true;$('patchSolution').hidden=true;const fb=$('codeFeedback');fb.className='feedback';
 if(l.typed){$('typedPatch').hidden=false;ch.hidden=true;$('patchInput').value=l.starter;$('patchInput').disabled=false;$('runPatch').disabled=false;const tc=$('testCases');tc.innerHTML='';for(const e of l.examples){const d=document.createElement('div');d.textContent=e;tc.appendChild(d)}fb.textContent='Type one JavaScript statement, then check your patch.';setTimeout(()=>{const i=$('patchInput');i.focus();i.setSelectionRange(i.value.length,i.value.length)},30)}
 else{$('typedPatch').hidden=true;ch.hidden=false;fb.textContent='Choose the code that fixes the bug.';l.choices.forEach((s,i)=>{const b=document.createElement('button');b.className='choice';b.type='button';b.textContent=s;b.addEventListener('click',()=>chooseAnswer(i,b));ch.appendChild(b)});setTimeout(()=>ch.firstChild&&ch.firstChild.focus(),30)}
 codeModal.hidden=false}
function success(l){const fb=$('codeFeedback');fb.className='feedback success';fb.innerHTML='';const s=document.createElement('strong');s.textContent='PATCH ACCEPTED. ';fb.appendChild(s);fb.appendChild(document.createTextNode(l.explain));$('codeContinue').hidden=false;$('codeContinue').focus();SFX.win()}
function chooseAnswer(i,btn){const l=LESSONS[activeTerm.lesson],fb=$('codeFeedback');if(i===l.answer){btn.classList.add('right');for(const b of $('codeChoices').children)b.disabled=true;success(l)}else{btn.classList.add('wrong');btn.disabled=true;attempts++;fb.className='feedback';fb.textContent='Not quite. Hint: '+l.hint;SFX.hurt()}}
function checkTyped(){const l=LESSONS[activeTerm.lesson],raw=$('patchInput').value,n=normCode(raw),fb=$('codeFeedback');
 if(!raw.trim()||n===normCode(l.starter)){fb.className='feedback';fb.textContent='Your patch is empty. Finish the line first.';return}
 if(l.accept.some(r=>r.test(n))){$('patchInput').disabled=true;$('runPatch').disabled=true;success(l);return}
 attempts++;const tip=l.tips.find(tp=>tp[0].test(n));fb.className='feedback';fb.textContent=(tip?tip[1]:'Not quite. Compare your line with the test cases and try again.')+(attempts>=2?' You can also view an example.':'');if(attempts>=2)$('patchSolution').hidden=false;SFX.hurt()}
function completePatch(){const t=activeTerm;if(!t)return;solved.add(t.lesson);score+=500;
 if(t.bossKey){t.item.taken=true;const b=level.boss;b.encrypted=false;b.keyDone=true;b.t=0;say('ARIA','Decrypted! Its core is exposed. Fire everything!');note('NULL.js DECRYPTED — ATTACK!',140)}
 else{t.solved=true;checkGate();say('ARIA',['Node patched. Agents are listening again.','Patch applied. Nice clean code.'][t.lesson%2])}
 activeTerm=null;codeModal.hidden=true;mode='playing';releaseControls();p.inv=Math.max(p.inv,40)}
$('codeContinue').addEventListener('click',completePatch);$('runPatch').addEventListener('click',checkTyped);
$('patchHint').addEventListener('click',()=>{const l=LESSONS[activeTerm.lesson];$('codeFeedback').className='feedback';$('codeFeedback').textContent='💡 '+l.hint});
$('patchSolution').addEventListener('click',()=>{const l=LESSONS[activeTerm.lesson];$('codeFeedback').className='feedback';$('codeFeedback').textContent='Example: '+l.solution+'  — type it yourself to understand each part.'});
$('patchInput').addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();checkTyped()}e.stopPropagation()});
$('codeLeave').addEventListener('click',()=>{if(!activeTerm)return;activeTerm.blocked=true;if(activeTerm.bossKey){activeTerm.item.taken=false;p.x=Math.max(camera+16,p.x-90)}activeTerm=null;codeModal.hidden=true;mode='playing';releaseControls()});

