for(const [id,src] of [['cpadL',UI_IMG.dpad],['cabrL',UI_IMG.abr],['consoleP',UI_IMG.console],['cmidL',UI_IMG.console]]){const el=$(id);if(el)el.style.backgroundImage=`url(${src})`}
for(const dz of document.querySelectorAll('.dz')){let pid=null;const ar={u:dz.querySelector('.u'),d:dz.querySelector('.d'),l:dz.querySelector('.l'),r:dz.querySelector('.r')};
 const setK=(k,v)=>{if(v&&!held[k])tapped[k]=true;held[k]=v};
 const apply=(L,R,U,D)=>{setK('left',L);setK('right',R);setK('up',U);const fl=!!(level&&level.flight);setK(fl?'down':'shield',D);setK(fl?'shield':'down',false);ar.l.classList.toggle('on',L);ar.r.classList.toggle('on',R);ar.u.classList.toggle('on',U);ar.d.classList.toggle('on',D)};
 const at=e=>{const r=dz.getBoundingClientRect(),dx=(e.clientX-r.left)/r.width*2-1,dy=(e.clientY-r.top)/r.height*2-1;apply(dx<-0.28,dx>0.28,dy<-0.32&&-dy>Math.abs(dx)*0.55,dy>0.32&&dy>Math.abs(dx)*0.55)};
 dz.addEventListener('pointerdown',e=>{e.preventDefault();if(['title','clear','over','won','cut'].includes(mode)){advance();return}if(mode==='paused'){togglePause();return}pid=e.pointerId;try{dz.setPointerCapture(pid)}catch(_){}at(e)});
 dz.addEventListener('pointermove',e=>{if(e.pointerId===pid)at(e)});
 const end=e=>{if(e.pointerId!==pid)return;pid=null;apply(false,false,false,false);held.down=false;held.shield=false};
 dz.addEventListener('pointerup',end);dz.addEventListener('pointercancel',end);dz.addEventListener('lostpointercapture',end)}
for(const id of ['cPause','cPause2'])$(id).addEventListener('pointerdown',e=>{e.preventDefault();if(mode==='playing'||mode==='paused')togglePause()});
for(const id of ['cOpts','cOpts2'])$(id).addEventListener('pointerdown',e=>{e.preventDefault();$('menuBtn').click()});
const fsOk=!!(document.fullscreenEnabled||document.webkitFullscreenEnabled);$('fullBtn').hidden=!fsOk;
$('fullBtn').addEventListener('click',async()=>{try{if(document.fullscreenElement||document.webkitFullscreenElement){await (document.exitFullscreen||document.webkitExitFullscreen).call(document)}else{const el=document.documentElement;await (el.requestFullscreen||el.webkitRequestFullscreen).call(el);try{await screen.orientation.lock('landscape')}catch(e){}}}catch(e){$('fullBtn').hidden=true}setTimeout(fitStage,150)});
document.addEventListener('fullscreenchange',()=>{$('fullBtn').textContent=document.fullscreenElement?'✕ Exit full screen':'⛶ Full screen';setTimeout(fitStage,100)});
